export {
  CompletedFocusTab,
  create,
  FocusedTab,
  FocusTab,
  init,
  initialize,
  Message,
  Model,
  OutMessage,
  Selected,
  SelectedTab,
} from "../tabs";
export type {
  ActivationMode,
  InitConfig,
  InitReturn,
  Orientation,
  RenderInfo,
  TabInfo,
  UpdateReturn,
  ViewInputs,
} from "../tabs";

export {
  baseUiTabsListClassName,
  baseUiTabsPanelClassName,
  baseUiTabsRootClassName,
  baseUiTabsTabClassName,
  baseUiTabsVerticalListClassName,
  baseUiTabsVerticalRootClassName,
  baseUiTabsView,
} from "./view";
export type { BaseUiTabsViewInput } from "./view";

export {
  panelClassName as baseUiTabsPanelClassName,
  tabClassName as baseUiTabsTabClassName,
  tabListClassName as baseUiTabsListClassName,
  tabsRootClassName as baseUiTabsRootClassName,
  tabsView as baseUiTabsView,
  verticalTabListClassName as baseUiTabsVerticalListClassName,
  verticalTabsRootClassName as baseUiTabsVerticalRootClassName,
} from "../tabs/view";
export type { TabsViewInput as BaseUiTabsViewInput } from "../tabs/view";

import { describe, expect, test } from "vitest";

import * as Tabs from "./index";

describe("Base UI Tabs registry view", () => {
  test("reuses the Foldkit Tabs functional contract", () => {
    expect(Tabs.init).toBeTypeOf("function");
    expect(Tabs.create).toBeTypeOf("function");
    expect(Tabs.baseUiTabsView).toBeTypeOf("function");
    expect(Tabs.baseUiTabsTabClassName).toContain("data-[selected]");
  });
});
